// neon.test.js — pure-logic tests for the game (no DOM, `node --test`).
//
// Run: `npm test`  (node --test "game/**/*.test.js")

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  resolveBricks,
  advance,
  makeBricks,
  createState,
  ballSpeed,
  comboMultiplier,
  scoreForBrick,
  MAX_COMBO_MULTIPLIER,
  MIN_VX_FRACTION,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  PADDLE_W,
  PADDLE_Y,
  BALL_R,
  BRICK_GAP,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// A lone brick, away from the walls, so one collision is exercised at a time
// without the grid's neighbours or the wall interfering.
function loneBrick() {
  return { x: 200, y: 100, w: 72, h: 20, row: 0, alive: true, points: 100 };
}

// --- Bricks: bounce resolution (the reported symptom: the ball plows straight
// --- through bricks). One test per defect family.

test('bricks: a top-face hit flips vy only', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = { x: 236, y: brick.y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.vy < 0, 'vy flips up');
  assert.equal(state.ball.vx, 0, 'vx untouched on a top-face hit');
  assert.equal(collides(state.ball, brick), false, 'ball is outside the brick');
  assert.equal(brick.alive, false, 'the brick breaks');
});

test('bricks: a side hit flips vx only', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = { x: brick.x - BALL_R - 0.5, y: brick.y + brick.h / 2, r: BALL_R, vx: ballSpeed(1), vy: 0 };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.vx < 0, 'vx flips left');
  assert.equal(state.ball.vy, 0, 'vy untouched on a side hit');
  assert.equal(collides(state.ball, brick), false, 'ball is outside the brick');
});

test('bricks: a corner hit flips both components', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = {
    x: brick.x - BALL_R - 0.5,
    y: brick.y - BALL_R - 0.5,
    r: BALL_R,
    vx: ballSpeed(1),
    vy: ballSpeed(1),
  };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components flip at a corner');
  assert.equal(collides(state.ball, brick), false, 'ball is outside the brick');
});

test('bricks: no tunneling at max level-6 speed in one capped step', () => {
  const state = createState(6);
  const brick = state.bricks[0]; // top of the grid
  // One capped step (ballSpeed(6) * 0.05 = 35.5px) is longer than the brick
  // plus the ball diameter (BRICK_H + 2 * BALL_R = 34px): a check at the final
  // position alone would skip the brick entirely.
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05);
  resolveBricks(state);
  assert.ok(state.ball.vy < 0, 'vy flips up: the ball bounced, not tunneled');
  assert.ok(state.ball.y + state.ball.r <= brick.y + 1e-6, 'ball ends above the brick');
  assert.equal(brick.alive, false);
});

test('bricks: an overlapping ball is pushed out and never re-inverts', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  // The ball overlaps the brick's top edge and is still moving down: the
  // previous resolution failed to separate it (the "sticky" case).
  state.ball = { x: 236, y: brick.y - 3, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  resolveBricks(state);
  assert.equal(collides(state.ball, brick), false, 'ball pushed out of the brick');
  assert.ok(state.ball.vy < 0, 'vy flipped once');
  const vy = state.ball.vy;
  resolveBricks(state); // a second pass must not re-invert
  assert.equal(state.ball.vy, vy, 'no double inversion');
});

test('bricks: a seam hit inverts once and never passes through', () => {
  const state = createState(1);
  const c0 = state.bricks[0];
  const c1 = state.bricks[1];
  const y = c0.y + c0.h / 2;
  // The ball sits on the vertical seam between two bricks, moving right:
  // resolving both bricks in one pass would invert vx twice and tunnel.
  state.ball = { x: c0.x + c0.w + BRICK_GAP / 2, y, r: BALL_R, vx: ballSpeed(1), vy: 0 };
  resolveBricks(state);
  assert.ok(state.ball.vx < 0, 'vx flipped left: bounced off the seam, not through it');
  assert.equal(collides(state.ball, c0), false, 'out of the brick it hit');
  assert.equal(c0.alive, false);
  assert.equal(c1.alive, true, 'one brick resolved per pass');
});

test('bricks: speed after a bounce equals the level speed', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  // An off-level norm (as an un-normalised paddle bounce would leave) must be
  // renormalised to the level speed by the bounce.
  state.ball = { x: 236, y: brick.y - BALL_R - 0.5, r: BALL_R, vx: 50, vy: ballSpeed(1) };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - ballSpeed(1)) < 1e-9);
});

test('physics: the same bounce at 30 fps and at 144 fps', () => {
  const run = (dt) => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
    for (let i = 0; i < 1000 && state.ball.vy > 0; i++) {
      step(state, dt);
      resolveBricks(state);
    }
    return { x: state.ball.x, y: state.ball.y, vx: state.ball.vx, vy: state.ball.vy, dead: brick.alive };
  };
  const at30 = run(1 / 30);
  const at144 = run(1 / 144);
  assert.equal(at30.dead, true);
  assert.equal(at144.dead, true);
  assert.ok(Math.abs(at30.y - at144.y) < 1e-9, 'same bounce position');
  assert.ok(Math.abs(at30.vy - at144.vy) < 1e-9, 'same bounce velocity');
});

test('score: a brick is scored once per hit', () => {
  const state = createState(1);
  const brick = loneBrick();
  state.bricks = [brick];
  state.ball = { x: 236, y: brick.y - BALL_R - 0.5, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.equal(brick.alive, false);
  assert.equal(state.combo, 1, 'combo incremented once');
  assert.equal(state.score, scoreForBrick(brick, 1), 'scored once');
});

test('bricks: a ball pressed against the wall stays inside the field', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // the first column reaches into the wall zone
  state.ball = { x: BALL_R, y: brick.y + brick.h / 2, r: BALL_R, vx: 0, vy: 0 };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.x >= BALL_R - 1e-9 && state.ball.x <= WIDTH - BALL_R + 1e-9, 'ball stays inside the field');
  assert.equal(brick.alive, false, 'the pressed brick breaks');
});

// --- Paddle: capture, tunneling and angle.

test('paddle: a fast ball cannot tunnel through the paddle', () => {
  const state = createState(1);
  // One capped step (ballSpeed(1) * 0.05 = 13px) can jump the ball's bottom
  // edge from above the paddle band to below it in a single frame.
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - 6.5, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'the ball is not lost');
  assert.ok(state.ball.vy < 0, 'vy flips up');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y + 1e-6, 'the ball exits through the top');
});

test('paddle: a paddle teleported onto the ball pushes it out the top', () => {
  const state = createState(1);
  // The mouse teleports the paddle over the ball: the ball starts the frame
  // inside the paddle band and must still bounce out through the top.
  state.paddle.x = WIDTH / 2 - PADDLE_W / 2;
  state.ball = { x: WIDTH / 2, y: PADDLE_Y + 2, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, 1 / 60);
  assert.equal(lost, false, 'the ball is not lost');
  assert.ok(state.ball.vy < 0, 'vy flips up');
  assert.ok(state.ball.y + state.ball.r <= PADDLE_Y + 1e-6, 'the ball exits through the top');
});

test('paddle: a dead-center hit keeps a playable angle', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60); // dead-center hit: hit = 0
  assert.ok(Math.abs(state.ball.vx) >= ballSpeed(1) * MIN_VX_FRACTION, 'vx is not (near) zero');
});

test('paddle: speed after a bounce equals the level speed', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.ball = { x: WIDTH / 2 + 24, y: PADDLE_Y - BALL_R - 1, r: BALL_R, vx: 0, vy: speed };
  step(state, 1 / 60); // off-center hit: hit = 0.5
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - speed) < 1e-9);
});

// --- Score & combo.

test('score: the combo multiplier is bounded', () => {
  assert.equal(comboMultiplier(1000), MAX_COMBO_MULTIPLIER);
  assert.equal(comboMultiplier(8), MAX_COMBO_MULTIPLIER); // 1 + 8 * 0.5 = 5
  assert.ok(comboMultiplier(0) < MAX_COMBO_MULTIPLIER);
});

// --- Transitions: level clear, lives, relaunch.

test('transitions: the level clears the frame the last brick dies', () => {
  const state = createState(1);
  state.bricks = [makeBricks(1)[0]];
  state.ball = { x: 40, y: 30, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, 0.05);
  resolveBricks(state);
  const result = advance(state, lost);
  assert.equal(lost, false);
  assert.equal(result, 'level');
  assert.equal(state.level, 2);
});

test('transitions: clearing the last brick while losing the ball costs no life', () => {
  const state = createState(1);
  state.bricks = [makeBricks(1)[0]];
  state.ball = { x: 40, y: 30, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  state.combo = 5;
  const lost = step(state, 5); // crosses the brick and exits the field
  resolveBricks(state);
  const result = advance(state, lost);
  assert.equal(lost, true);
  assert.equal(result, 'level', 'the level wins over the life loss');
  assert.equal(state.lives, 3, 'no life lost');
  assert.equal(state.level, 2);
  assert.equal(state.combo, 0, 'combo reset on level up');
  assert.equal(state.bricks.length, BRICK_ROWS * BRICK_COLS, 'fresh grid');
});

test('transitions: one life is lost per exit', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: 500, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
  assert.equal(advance(state, lost), 'life');
  assert.equal(state.lives, 2);
  assert.equal(advance(state, false), 'none');
  assert.equal(state.lives, 2, 'no second life lost');
});

test('transitions: game over resets the run', () => {
  const state = createState(1);
  state.lives = 1;
  state.ball = { x: WIDTH / 2, y: 500, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  const lost = step(state, 1 / 60);
  assert.equal(advance(state, lost), 'over');
  assert.equal(state.lives, 3);
  assert.equal(state.level, 1);
});

