// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Pure logic (physics, collision, score) lives in exported functions tested
// from `node --test`; rendering lives in `frame()`; only `boot()` touches the
// DOM. The module runs nothing on import.

export const BALL_R = 7;

// Bounce-resolution tolerance: a ball is placed this far beyond the face it
// bounces off, so floating-point noise never leaves it overlapping.
const EPS = 0.001;
// The narrowest horizontal angle (as a fraction of the level speed) the
// paddle bounce may produce: a dead-center hit must stay playable.
export const MIN_VX_FRACTION = 0.2;
// Upper bound of the combo multiplier (1 + combo * 0.5).
export const MAX_COMBO_MULTIPLIER = 5;

