// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  // Launch at 30° from the vertical so the norm is exactly `speed`.
  const vx = speed * 0.5;
  const vy = -speed;
  const norm = Math.hypot(vx, vy);
  const x = WIDTH / 2;
  const y = PADDLE_Y - BALL_R - 2;
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: {
      x,
      y,
      px: x,
      py: y,
      r: BALL_R,
      vx: (vx / norm) * speed,
      vy: (vy / norm) * speed,
    },
    bricks: makeBricks(level),
  };
}

