// True if the circle (ball) overlaps the brick: simple AABB test. It only
// says WHETHER they overlap, not which face was hit — the bounce is decided
// in `resolveBricks()` from the swept path.
export function collides(ball, brick) {
  return overlaps(ball.x, ball.y, ball.r, brick);
}

// Scalar form of the same test, used by the swept resolution.
function overlaps(x, y, r, brick) {
  return (
    x + r > brick.x &&
    x - r < brick.x + brick.w &&
    y + r > brick.y &&
    y - r < brick.y + brick.h
  );
}

