// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Bricks are handled separately by `resolveBricks()`.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the step started: `resolveBricks()` sweeps from there to the
  // new position, which is what stops tunneling.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
    setSpeed(state);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
    setSpeed(state);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
    setSpeed(state);
  }

