// --- Transitions (pure, tested) --------------------------------------------

// Applies the end-of-frame transitions. A cleared level wins over a ball lost
// in the same step (no life is spent on a cleared level); a lost ball costs
// one life and relaunches; running out of lives resets the run. The combo is
// reset on every relaunch, life lost and level up. Returns
// 'level' | 'life' | 'over' | 'none'.
export function advance(state, lost) {
  if (state.bricks.every((b) => !b.alive)) {
    state.level += 1;
    state.combo = 0;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
    return 'level';
  }
  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      saveBest(globalThis.localStorage, state.score);
      Object.assign(state, createState(state.level));
      state.best = loadBest(globalThis.localStorage);
      return 'over';
    }
    state.ball = createState(state.level).ball;
    return 'life';
  }
  return 'none';
}

// --- Boot (browser entry point) --------------------------------------------

if (state.running) {
  const lost = step(state, dt);
  resolveBricks(state);
  advance(state, lost);
}

