// Paddle: swept over the ball's path — a fast ball, or a paddle the mouse
// teleported onto the ball, always bounces out through the top.
const prevBottom = ball.py + ball.r;
const newBottom = ball.y + ball.r;
if (
  ball.vy > 0 &&
  prevBottom <= paddle.y + paddle.h &&
  newBottom >= paddle.y &&
  ball.x + ball.r >= paddle.x &&
  ball.x - ball.r <= paddle.x + paddle.w
) {
  ball.y = paddle.y - ball.r;
  const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
  ball.vx = ballSpeed(state.level) * 0.6 * hit;
  ball.vy = -Math.abs(ball.vy);
  setSpeed(state);
  // A dead-center hit would leave vx = 0 and the ball bouncing straight up
  // forever: guarantee a playable angle (norm stays the level speed).
  const minVx = ballSpeed(state.level) * MIN_VX_FRACTION;
  if (Math.abs(ball.vx) < minVx) {
    ball.vx = minVx * (ball.vx < 0 ? LEFT : RIGHT);
    ball.vy = -Math.sqrt(Math.max(0, ballSpeed(state.level) ** 2 - minVx ** 2));
  }
  state.combo = 0; // touching the paddle resets the combo
}

